bash: cd /app
bite() { desc=$1; shift; "$@" >/dev/null 2>&1; ./scripts/verify.sh >/tmp/v.log 2>&1; rc=$?; echo "[$desc] verify exit=$rc (expect 1) -> $(grep -c '  FAIL' /tmp/v.log) FAIL line(s)"; }
mvdist() { rm -rf dist; }
restore_dist() { ./scripts/build.sh >/dev/null 2>&1 && ./scripts/start_index.sh >/dev/null 2>&1; }

echo "### SABOTAGE 1: remove dist/"
mv dist /tmp/dist_bak
./scripts/verify.sh >/tmp/v.log 2>&1; echo "  exit=$? (expect 1)"; grep '  FAIL' /tmp/v.log | head -4
mv /tmp/dist_bak dist
